(44, 2, 15, 6, 'Objetivo do cargo:\r\nGarantir a organização, controle e movimentação correta dos produtos no estoque, bem como apoiar os processos logísticos de entrada, armazenamento, separação e expedição de mercadorias, assegurando agilidade, precisão e cumprimento de prazos da AZZO Distribuidora.\r\nPrincipais atividades:\r\nReceber, conferir e armazenar produtos de higiene no estoque;\r\nRealizar a organização do estoque, mantendo os produtos identificados e corretamente armazenados;\r\nControlar entradas e saídas de mercadorias;\r\nSeparar, conferir e preparar pedidos para envio;\r\nEmitir NF-e e etiquetas para pedidos;\r\nApoiar o carregamento e descarregamento de mercadorias;\r\nAuxiliar no controle de inventário e contagem de produtos;\r\nZelar pela limpeza e organização do ambiente de estoque.\r\nResponsabilidades:\r\nGarantir a correta conferência dos produtos recebidos e enviados;\r\nManter o controle adequado do estoque, evitando faltas, excessos ou perdas;\r\nCumprir prazos de separação, emissão de documentos e expedição dos pedidos;\r\nPreservar a integridade dos produtos armazenados;\r\nSeguir os processos e orientações internas da empresa.', 6, NULL, 'Mario Marcondes Moreira Neto', '17081876773', '64533574000108', '37740000', '10A RUA JOAQUIM FRANCISCO BARBOSA', '208', '', 'ITAMARATY', 'BANDEIRA DO SUL', 'MG', '', '34.022.533-3', '1999-05-23', 'solteiro', '(21) 9.8548-9276', 'mario.boris123@gmail.com', '2026-01-19', 'desligado', 'PJ', 8.00, NULL, 10.58, '64.533.574/0001-08', '', '', 'elielandolfo@gmail.com', '', '', NULL, '$2y$12$dLTuhz9K3ezU4s8N9/joruwPH3JV.UNGNACeCh2K9dBCf2Eo5bi1G', '2026-01-22 14:53:47', '2026-05-15 16:17:34', NULL, 1, NULL, 1),
(45, 1, 1, 1, 'Cargo:\r\nAuxiliar de Produção\r\nObjetivo do cargo:\r\nAuxiliar em todos os processos da produção de brindes personalizados, apoiando a operação das máquinas e garantindo que os produtos sejam produzidos com qualidade, organização e dentro dos padrões da Personizi.\r\nPrincipais atividades:\r\nAuxiliar em todas as etapas do processo de produção de brindes personalizados;\r\nOperar máquinas e equipamentos conforme orientação e treinamento;\r\nAtuar de forma rotativa nos diferentes processos da produção, sempre que necessário;\r\nConferir os produtos antes do início da produção;\r\nRealizar a contagem dos produtos antes de produzir;\r\nApoiar a equipe em demandas gerais da produção.\r\nResponsabilidades:\r\nManter o ambiente de trabalho limpo, organizado e seguro;\r\nGarantir a conferência correta dos produtos antes da produção;\r\nZelar pela qualidade de cada item produzido;\r\nSeguir os processos e orientações estabelecidos pela empresa;\r\nContribuir para o bom andamento da produção e cumprimento de prazos.', 6, NULL, 'Victor Gutemberg Felipini', '47755508889', '64689939000198', '37701104', 'Mario de Paiva', '42', '', 'Vila nova', 'Poços de Caldas', 'MG', '', '47755508889', '1999-02-03', 'casado', '35997456106', 'gutembergfelipini7@gmail.com', '2026-01-19', 'ativo', 'PJ', 8.00, NULL, 11.11, '64689939000198', '', '', 'elielandolfo@gmail.com', '', '', NULL, '$2y$12$KgPdJvIVxJGeIq/lTGUdn.4ivnEecLUQ5FVkAMvCPN9gYELrtayzy', '2026-01-26 14:09:57', '2026-05-15 17:14:34', NULL, 1, NULL, 1),
